#!/usr/bin/env bash
set -u

export PATH="$HOME/.local/bin:/usr/local/bin:/usr/bin:/bin"

# Multibyte output (icons, °C) needs a UTF-8 locale. Bare installs often leave
# LANG unset, which makes bash print '\uXXXX' escapes literally instead of the
# glyph. Force a UTF-8 locale for this script when none is set and one exists.
if [[ -z ${LC_ALL:-} && -z ${LANG:-} ]]; then
  for _loc in C.UTF-8 en_US.UTF-8; do
    if command -v locale >/dev/null 2>&1 && locale -a 2>/dev/null | grep -qxF "$_loc"; then
      export LANG="$_loc"; break
    fi
  done
  unset _loc
fi

XSETROOT="$(command -v xsetroot || true)"
# Detect whether the running dwm supports status2d/statuscmd (built with the
# NIRUPI patches). On an older dwm we must NOT emit colour codes or section
# bytes, or they would render as garbage.
DWM_STATUS2D=0
_nirupi_dwm_bin="$(readlink -f "$HOME/.local/bin/dwm" 2>/dev/null || true)"
if [[ -n "$_nirupi_dwm_bin" && -r "$_nirupi_dwm_bin" ]] && command -v strings >/dev/null 2>&1; then
  if strings "$_nirupi_dwm_bin" 2>/dev/null | grep -q 'nirupi-status-click'; then DWM_STATUS2D=1; fi
fi
DATEBIN="$(command -v date || true)"
HOSTNAMEBIN="$(command -v hostname || true)"
NMCLI="$(command -v nmcli || true)"
CHECKUPDATES="$HOME/.local/bin/nirupi-updates"
FREEBIN="$(command -v free || true)"
UPTIMEBIN="$(command -v uptime || true)"

INTERVAL="${NIRUPI_BAR_INTERVAL:-2}"
TEMP_WARN=70
UPDATES_CACHE_SECONDS=1800
MEDIA_CACHE_SECONDS=300
NETWORK_CACHE_SECONDS=20
NEXTCLOUD_CACHE_SECONDS=60
DISK_WARN_PERCENT=90

SHOW_MEDIA=1
SHOW_VOLUME=1
SHOW_NOW_PLAYING=1
SHOW_PLAYER_NAME=1
SHOW_MEMORY=0
SHOW_UPTIME=0
SHOW_UPDATES=1
SHOW_TEMP=1
SHOW_BATTERY=1
SHOW_NETWORK=1
SHOW_DISK=0
SHOW_CPU=0
SHOW_LOAD=0
SHOW_BLUETOOTH=0
SHOW_MIC=1
SHOW_DND=1
SHOW_RECORDING=1
SHOW_CAFFEINE=1
SHOW_NEXTCLOUD=1
USE_ICONS=1
SHOW_KERNEL=1
SHOW_HOST=1
SHOW_WEATHER=1
SHOW_DATE=1
SHOW_TIME=1

# Bar colour: monochrome in Noir; colour only in wallpaper mode, unless the
# user explicitly sets BAR_COLOR=1 in status.conf (then that always wins).
BAR_COLOR=0
BAR_COLOR_EXPLICIT=0
_theme_mode_file="${XDG_CONFIG_HOME:-$HOME/.config}/nirupi/theme.mode"

# ── Weather (default: Ljungskile, Sweden) ─────────────────────────────────────
WEATHER_CITY="Ljungskile"
WEATHER_LAT="58.2167"
WEATHER_LON="11.9333"
WEATHER_TIMEZONE="Europe/Stockholm"
WEATHER_INTERVAL_SECONDS=900    # current conditions, refreshed every 15 minutes

# Media roots. Leave empty for auto-detect.
MEDIA_MUSIC_DIR="${NIRUPI_MUSIC_DIR:-}"
MEDIA_PHOTOS_DIR="${NIRUPI_PHOTOS_DIR:-}"
MEDIA_VIDEOS_DIR="${NIRUPI_VIDEOS_DIR:-}"

# Now playing behavior
NOW_PLAYING_MAXLEN=20
NOW_PLAYING_SCROLL=1
NOW_PLAYING_SCROLL_DELAY=3
NOW_PLAYING_SCROLL_STEP=1
NOW_PLAYING_FRAME_INTERVAL=0.3  # seconds; music animation only
NOW_PLAYING_SCROLL_PASSES=0  # 0 = continuous
NOW_PLAYING_LABEL_SEPARATOR=": "
NOW_PLAYING_PREFERRED_PLAYERS="nplay spotify mpv kew cmus brave chromium firefox"

# Optional user settings. This file is never overwritten by NIRUPI.
# It is sourced as the current user: edit only your own trusted file.
NIRUPI_STATUS_CONFIG="${XDG_CONFIG_HOME:-$HOME/.config}/nirupi/status.conf"
if [[ -f "$NIRUPI_STATUS_CONFIG" && ! -L "$NIRUPI_STATUS_CONFIG" ]]; then
  source "$NIRUPI_STATUS_CONFIG"
fi
if [[ -f "$NIRUPI_STATUS_CONFIG" ]] && grep -q '^[[:space:]]*BAR_COLOR=' "$NIRUPI_STATUS_CONFIG" 2>/dev/null; then
  BAR_COLOR_EXPLICIT=1
fi

# Theme accent colours (generated by `nirupi theme apply`). Defaults keep the
# original Noir accents when the generated file is missing.
NIRUPI_THEME_ENV="${XDG_CONFIG_HOME:-$HOME/.config}/nirupi/theme/status.env"
if [[ -f "$NIRUPI_THEME_ENV" && ! -L "$NIRUPI_THEME_ENV" ]]; then
  source "$NIRUPI_THEME_ENV"
fi
: "${NIRUPI_C_RED:=b87878}"
: "${NIRUPI_C_MUTED:=a8a8a8}"
: "${NIRUPI_C_YELLOW:=b5a47e}"
: "${NIRUPI_C_BLUE:=819eb5}"
: "${NIRUPI_C_CYAN:=83a9a7}"

CACHE_DIR="${XDG_CACHE_HOME:-$HOME/.cache}/dwm-status"
UPDATES_FILE="$CACHE_DIR/updates.count"
UPDATES_STAMP="$CACHE_DIR/updates.stamp"
UPDATES_DB_STAMP="$CACHE_DIR/updates.db-stamp"
MEDIA_CACHE_FILE="$CACHE_DIR/media.count"
MEDIA_CACHE_STAMP="$CACHE_DIR/media.stamp"
NP_STATE_FILE="$CACHE_DIR/nowplaying.state"
NP_TEXT_FILE="$CACHE_DIR/nowplaying.text"
NP_SEEN_FILE="$CACHE_DIR/nowplaying.seen"
NP_OFFSET_FILE="$CACHE_DIR/nowplaying.offset"
NP_PASSES_FILE="$CACHE_DIR/nowplaying.passes"
NP_CURRENT_FILE="$CACHE_DIR/nowplaying.current"
WEATHER_CACHE_FILE="$CACHE_DIR/weather.json"
WEATHER_CACHE_STAMP="$CACHE_DIR/weather.stamp"
PROVIDER_DIR="$CACHE_DIR/providers"

mkdir -p "$CACHE_DIR" "$PROVIDER_DIR"
# Cache an expensive provider for a number of seconds: provider_cached NAME TTL CMD...
provider_cached() {
  local name="$1" ttl="$2"; shift 2
  local file="$PROVIDER_DIR/$name" stamp_file="$PROVIDER_DIR/$name.stamp"
  local now stamp age value
  now="$($DATEBIN +%s 2>/dev/null || printf '0')"
  stamp=0
  [[ -r "$stamp_file" ]] && stamp="$(tr -d '[:space:]' < "$stamp_file" 2>/dev/null)"
  [[ "$stamp" =~ ^[0-9]+$ ]] || stamp=0
  age=$((now - stamp))
  # kernel/host change rarely but must not be shown stale: tie the cache to the
  # running kernel/hostname so a change invalidates it immediately.
  if [[ $name == kernel || $name == host ]]; then
    local src=""
    case $name in
      kernel) src="$(uname -r 2>/dev/null || printf '')";;
      host)   src="$(cat /etc/hostname 2>/dev/null || uname -n 2>/dev/null || printf '')";;
    esac
    if [[ -r "$PROVIDER_DIR/$name.src" && "$(cat "$PROVIDER_DIR/$name.src" 2>/dev/null)" == "$src" ]]; then
      :
    else
      printf '%s' "$src" > "$PROVIDER_DIR/$name.src" 2>/dev/null || true
      stamp=0
    fi
  fi
  if [[ -r "$file" && "$age" -ge 0 && "$age" -lt "$ttl" ]]; then
    cat "$file"
    return 0
  fi
  value="$("$@" 2>/dev/null || true)"
  printf '%s\n' "$value" > "$file" 2>/dev/null || true
  printf '%s\n' "$now" > "$stamp_file" 2>/dev/null || true
  printf '%s' "$value"
}

# status2d / statuscmd helpers -------------------------------------------------
# sect ID TEXT   -> wrap a clickable section with the raw section id byte
sect() {
  local id="$1"; shift
  if [[ "${DWM_STATUS2D:-0}" -eq 1 ]]; then
    printf "\\$(printf '%03o' "$id")%s\\$(printf '%03o' "$id")" "$*"
  else
    printf '%s' "$*"
  fi
}
# colorc RRGGBB TEXT -> status2d coloured text (resets to SchemeNorm afterwards)
colorc() { if [[ "${DWM_STATUS2D:-0}" -eq 1 ]]; then printf '^c#%s^%s^d^' "$1" "$2"; else printf '%s' "$2"; fi; }
bar_color_on(){
  [[ "${DWM_STATUS2D:-0}" -eq 1 ]] || return 1
  if [[ "${BAR_COLOR_EXPLICIT:-0}" -eq 1 ]]; then
    [[ "${BAR_COLOR:-0}" -eq 1 ]]
  else
    local _mode=""
    [[ -r "$_theme_mode_file" ]] && _mode="$(tr -d '[:space:]' < "$_theme_mode_file" 2>/dev/null)"
    [[ "$_mode" == wallpaper ]]
  fi
}
# Keep exactly one bar writer per user/X display, including concurrent startx/SDDM starts.
if command -v flock >/dev/null 2>&1; then
  display_key="${DISPLAY:-no-display}"
  display_key="${display_key//[^a-zA-Z0-9_-]/_}"
  exec 9>"$CACHE_DIR/status-${display_key}.lock"
  flock -n 9 || exit 0
fi

# Now playing state is persisted in cache files so it survives subshells.

