wmo_emoji() {
  if [[ "$USE_ICONS" -ne 1 ]]; then
    case "$1" in
      0)                        printf 'sun' ;;
      1|2|3)                    printf 'cloud' ;;
      45|48)                    printf 'fog' ;;
      51|53|55)                 printf 'drizzle' ;;
      61|63|65|66|67|80|81|82)  printf 'rain' ;;
      71|73|75|77|85|86)        printf 'snow' ;;
      95|96|99)                 printf 'storm' ;;
      *)                        printf '?' ;;
    esac
    return 0
  fi
  case "$1" in
    0)                        printf '' ;;  # sun
    1|2|3)                    printf '' ;;  # cloud
    45|48)                    printf '' ;;  # fog
    51|53|55)                 printf '' ;;  # drizzle
    61|63|65|66|67|80|81|82)  printf '' ;;  # rain
    71|73|75|77|85|86)        printf '' ;;  # snow
    95|96|99)                 printf '' ;;  # storm
    *)                        printf '' ;;  # question
  esac
}

get_weather() {
  [[ "$SHOW_WEATHER" -eq 1 ]] || return 0
  [[ -n "$WEATHER_LAT" && -n "$WEATHER_LON" ]] || return 0
  command -v curl >/dev/null 2>&1 || return 0
  command -v jq   >/dev/null 2>&1 || return 0

  local now stamp age json code temp emoji
  now="$($DATEBIN +%s 2>/dev/null || printf '0')"
  stamp=0

  [[ -r "$WEATHER_CACHE_STAMP" ]] && \
    stamp="$(tr -d '[:space:]' < "$WEATHER_CACHE_STAMP" 2>/dev/null || printf '0')"
  [[ "$stamp" =~ ^[0-9]+$ ]] || stamp=0

  age=$(( now - stamp ))

  if [[ ! -r "$WEATHER_CACHE_FILE" || "$age" -ge "$WEATHER_INTERVAL_SECONDS" ]]; then
    json="$(curl -sf --max-time 8 \
      "https://api.open-meteo.com/v1/forecast?latitude=${WEATHER_LAT}&longitude=${WEATHER_LON}&current=temperature_2m,weather_code&timezone=${WEATHER_TIMEZONE}" \
      2>/dev/null)" || true
    if [[ -n "$json" ]] && printf '%s' "$json" | jq -e '.current' >/dev/null 2>&1; then
      printf '%s\n' "$json" > "$WEATHER_CACHE_FILE" 2>/dev/null || true
      printf '%s\n' "$now"  > "$WEATHER_CACHE_STAMP" 2>/dev/null || true
    fi
  fi

  [[ -r "$WEATHER_CACHE_FILE" ]] || return 0

  code="$(jq -r '.current.weather_code // empty' "$WEATHER_CACHE_FILE" 2>/dev/null)"
  temp="$(jq -r '.current.temperature_2m | round' "$WEATHER_CACHE_FILE" 2>/dev/null)"

  [[ -n "$code" && -n "$temp" ]] || return 0

  emoji="$(wmo_emoji "$code")"
  printf '%s %s°C' "$emoji" "$temp"
}

icon_battery_for_level() {
  local level="$1"
  local charging="${2:-0}"

  if [[ "$USE_ICONS" -ne 1 ]]; then
    if [[ "$charging" -eq 1 ]]; then
      printf 'bat+'
    else
      printf 'bat'
    fi
    return 0
  fi

  if [[ "$charging" -eq 1 ]]; then
    if (( level >= 95 )); then printf '󰂅'
    elif (( level >= 90 )); then printf '󰂋'
    elif (( level >= 80 )); then printf '󰂊'
    elif (( level >= 70 )); then printf '󰢞'
    elif (( level >= 60 )); then printf '󰂉'
    elif (( level >= 50 )); then printf '󰢝'
    elif (( level >= 40 )); then printf '󰂈'
    elif (( level >= 30 )); then printf '󰂇'
    elif (( level >= 20 )); then printf '󰂆'
    else printf '󰢜'
    fi
  else
    if (( level >= 95 )); then printf '󰁹'
    elif (( level >= 90 )); then printf '󰂂'
    elif (( level >= 80 )); then printf '󰂁'
    elif (( level >= 70 )); then printf '󰂀'
    elif (( level >= 60 )); then printf '󰁿'
    elif (( level >= 50 )); then printf '󰁾'
    elif (( level >= 40 )); then printf '󰁽'
    elif (( level >= 30 )); then printf '󰁼'
    elif (( level >= 20 )); then printf '󰁻'
    elif (( level >= 10 )); then printf '󰁺'
    else printf '󰂎'
    fi
  fi
}

normalize_player_name() {
  local name="$1"
  name="${name##*.}"
  case "$name" in
    spotify|mpv|kew|cmus|brave|chromium|firefox)
      printf '%s' "$name"
      ;;
    chromium-browser)
      printf 'chromium'
      ;;
    org\.mpris\.MediaPlayer2.*)
      printf '%s' "${name##*.}"
      ;;
    *)
      printf '%s' "$name"
      ;;
  esac
}

truncate_text() {
  local text="$1"
  local maxlen="${2:-20}"

  [[ -n "${text:-}" ]] || return 0

  if (( ${#text} > maxlen )); then
    printf '%s...' "${text:0:maxlen}"
  else
    printf '%s' "$text"
  fi
}

render_now_playing_text() {
  local full="$1"
  local now maxlen delay step max_passes visible
  local last_text first_seen np_offset np_state np_passes

  maxlen="${NOW_PLAYING_MAXLEN:-20}"
  delay="${NOW_PLAYING_SCROLL_DELAY:-3}"
  step="${NOW_PLAYING_SCROLL_STEP:-1}"
  max_passes="${NOW_PLAYING_SCROLL_PASSES:-2}"
  [[ "$maxlen" =~ ^[1-9][0-9]*$ ]] || maxlen=20
  [[ "$delay" =~ ^[0-9]+$ ]] || delay=3
  [[ "$step" =~ ^[1-9][0-9]*$ ]] || step=1
  [[ "$max_passes" =~ ^[0-9]+$ ]] || max_passes=0
  (( maxlen > 200 )) && maxlen=200
  (( step > maxlen )) && step=maxlen
  now="$($DATEBIN +%s 2>/dev/null || printf '0')"

  last_text=""
  first_seen=0
  np_offset=0
  np_state="pause"
  np_passes=0

  [[ -r "$NP_TEXT_FILE" ]] && last_text="$(cat "$NP_TEXT_FILE" 2>/dev/null || true)"
  [[ -r "$NP_SEEN_FILE" ]] && first_seen="$(tr -d '[:space:]' < "$NP_SEEN_FILE" 2>/dev/null || printf '0')"
  [[ -r "$NP_OFFSET_FILE" ]] && np_offset="$(tr -d '[:space:]' < "$NP_OFFSET_FILE" 2>/dev/null || printf '0')"
  [[ -r "$NP_STATE_FILE" ]] && np_state="$(tr -d '[:space:]' < "$NP_STATE_FILE" 2>/dev/null || printf 'pause')"
  [[ -r "$NP_PASSES_FILE" ]] && np_passes="$(tr -d '[:space:]' < "$NP_PASSES_FILE" 2>/dev/null || printf '0')"

  [[ "$first_seen" =~ ^[0-9]+$ ]] || first_seen=0
  [[ "$np_offset" =~ ^[0-9]+$ ]] || np_offset=0
  [[ "$np_passes" =~ ^[0-9]+$ ]] || np_passes=0
  [[ "$max_passes" =~ ^[0-9]+$ ]] || max_passes=0
  [[ "$np_state" == "pause" || "$np_state" == "scroll" || "$np_state" == "done" ]] || np_state="pause"

  if [[ "$full" != "$last_text" ]]; then
    last_text="$full"
    first_seen="$now"
    np_offset=0
    np_state="pause"
    np_passes=0
  fi

  if (( ${#full} <= maxlen )) || [[ "${NOW_PLAYING_SCROLL:-1}" -eq 0 ]]; then
    printf '%s\n' "$full" > "$NP_TEXT_FILE" 2>/dev/null || true
    printf '%s\n' "$first_seen" > "$NP_SEEN_FILE" 2>/dev/null || true
    printf '%s\n' '0' > "$NP_OFFSET_FILE" 2>/dev/null || true
    printf '%s\n' 'pause' > "$NP_STATE_FILE" 2>/dev/null || true
    printf '%s\n' '0' > "$NP_PASSES_FILE" 2>/dev/null || true
    printf '%s' "$full"
    return 0
  fi

  case "$np_state" in
    pause)
      visible="${full:0:maxlen}"
      if (( now - first_seen >= delay )); then
        np_state="scroll"
        np_offset=1
      fi
      ;;
    scroll)
      # Include a visible gap, then wrap seamlessly back to the artist.
      local cycle="${full}   "
      local cycle_len=${#cycle}
      local doubled="$cycle$cycle"
      while (( ${#doubled} < cycle_len + maxlen )); do doubled+="$cycle"; done
      visible="${doubled:np_offset:maxlen}"
      # Clamp the step to avoid skipping the wrap boundary.
      (( step > maxlen )) && step=maxlen
      np_offset=$(( (np_offset + step) % cycle_len ))
      if (( np_offset < step )); then
        np_passes=$((np_passes + 1))
        first_seen="$now"
        if (( max_passes > 0 && np_passes >= max_passes )); then
          np_state="done"
        else
          np_state="pause"
        fi
      fi
      ;;
    done)
      visible="${full:0:maxlen}"
      np_state="done"
      np_offset=0
      ;;
    *)
      visible="${full:0:maxlen}"
      np_state="pause"
      np_offset=0
      np_passes=0
      first_seen="$now"
      ;;
  esac

  printf '%s\n' "$full" > "$NP_TEXT_FILE" 2>/dev/null || true
  printf '%s\n' "$first_seen" > "$NP_SEEN_FILE" 2>/dev/null || true
  printf '%s\n' "$np_offset" > "$NP_OFFSET_FILE" 2>/dev/null || true
  printf '%s\n' "$np_state" > "$NP_STATE_FILE" 2>/dev/null || true
  printf '%s\n' "$np_passes" > "$NP_PASSES_FILE" 2>/dev/null || true

  printf '%s' "$visible"
}

get_kernel() {
  [[ "$SHOW_KERNEL" -eq 1 ]] || return 0
  local k short
  k="$(uname -r 2>/dev/null)"
  short="$(printf '%s' "$k" | cut -d- -f1)"

  case "$k" in
    *cachyos*) printf '%s-cachy' "$short" ;;
    *arch*) printf '%s-arch' "$short" ;;
    *) printf '%s' "$short" ;;
  esac
}

get_hostname() {
  [[ "$SHOW_HOST" -eq 1 ]] || return 0
  # `hostname` is not in a vanilla Arch base; fall back to /etc/hostname/uname.
  { [[ -n "$HOSTNAMEBIN" ]] && "$HOSTNAMEBIN" 2>/dev/null; } \
    || cat /etc/hostname 2>/dev/null \
    || uname -n 2>/dev/null \
    || printf 'host?'
}

get_network() {
  [[ "$SHOW_NETWORK" -eq 1 ]] || return 0
  [[ -x "$NMCLI" ]] || return 0

  local eth wifi_line wifi_name wifi_signal

  eth="$($NMCLI -t -f DEVICE,TYPE,STATE device status 2>/dev/null \
    | awk -F: '$2=="ethernet" && $3=="connected" {print $1; exit}')"

  if [[ -n "${eth:-}" ]]; then
    printf '%s' "$(icon_net)"
    return 0
  fi

  wifi_line="$($NMCLI -t -f IN-USE,SSID,SIGNAL device wifi list 2>/dev/null \
    | awk -F: '$1=="*" {print; exit}')"
  wifi_name="${wifi_line#*:}"
  wifi_name="${wifi_name%%:*}"
  wifi_signal="${wifi_line##*:}"

  if [[ -n "${wifi_name:-}" ]]; then
    # Just the icon and signal strength: the SSID eats bar space and is visible
    # in the click picker. Set SHOW_SSID=1 in status.conf to include it.
    if [[ "${SHOW_SSID:-0}" -eq 1 ]]; then
      if [[ -n "${wifi_signal:-}" ]]; then
        printf '%s %s %s%%' "$(icon_wifi)" "$wifi_name" "$wifi_signal"
      else
        printf '%s %s' "$(icon_wifi)" "$wifi_name"
      fi
    else
      if [[ -n "${wifi_signal:-}" ]]; then
        printf '%s %s%%' "$(icon_wifi)" "$wifi_signal"
      else
        printf '%s' "$(icon_wifi)"
      fi
    fi
    return 0
  fi

  printf '%s offline' "$(icon_net)"
}

get_battery() {
  [[ "$SHOW_BATTERY" -eq 1 ]] || return 0

  if ! find /sys/class/power_supply -maxdepth 1 -type l -name 'BAT*' | grep -q .; then
    return 0
  fi

  local bat cap status icon charging=0

  bat="$(
    for d in /sys/class/power_supply/*; do
      [[ -d "$d" ]] || continue
      [[ -r "$d/type" ]] || continue
      if grep -qx 'Battery' "$d/type" 2>/dev/null; then
        printf '%s\n' "$d"
        break
      fi
    done
  )"

  [[ -n "${bat:-}" ]] || return 0
  [[ -r "$bat/capacity" ]] || return 0

  cap="$(tr -d '[:space:]' < "$bat/capacity" 2>/dev/null)"
  [[ "$cap" =~ ^[0-9]+$ ]] || return 0

  status=""
  [[ -r "$bat/status" ]] && status="$(tr -d '[:space:]' < "$bat/status" 2>/dev/null)"

  case "$status" in
    Charging|Full) charging=1 ;;
    *) charging=0 ;;
  esac

  icon="$(icon_battery_for_level "$cap" "$charging")"

  local secs="" tstr="" suffix=""
  if [[ "$charging" -eq 0 && -r "$bat/time_to_empty_now" ]]; then
    secs="$(tr -d '[:space:]' < "$bat/time_to_empty_now" 2>/dev/null)"
  elif [[ "$charging" -eq 1 && -r "$bat/time_to_full_now" ]]; then
    secs="$(tr -d '[:space:]' < "$bat/time_to_full_now" 2>/dev/null)"
  fi
  if [[ "${secs:-}" =~ ^[0-9]+$ ]] && (( secs > 0 )); then
    tstr="$(printf '%dh%02dm' $((secs / 3600)) $(((secs % 3600) / 60)))"
  fi

  if [[ "$cap" -le 15 && "$charging" -eq 0 ]]; then suffix='!'; fi

  if [[ "$status" == "Full" ]]; then
    printf '%s %s%% full' "$icon" "$cap"
  elif [[ -n "$tstr" ]]; then
    printf '%s %s%%%s %s' "$icon" "$cap" "$suffix" "$tstr"
  else
    printf '%s %s%%%s' "$icon" "$cap" "$suffix"
  fi
}

get_temp_high() {
  [[ "$SHOW_TEMP" -eq 1 ]] || return 0

  # Glob (not find): /sys/class/hwmon/hwmonN are symlinks that find will not
  # descend into by default.
  local best=0 file raw temp_c
  local -a files=()
  for file in /sys/class/hwmon/hwmon*/temp*_input; do
    [[ -r "$file" ]] && files+=("$file")
  done
  if (( ${#files[@]} == 0 )); then
    for file in /sys/class/thermal/thermal_zone*/temp; do
      [[ -r "$file" ]] && files+=("$file")
    done
  fi

  for file in "${files[@]}"; do
    raw="$(tr -d '[:space:]' < "$file" 2>/dev/null)"
    [[ "$raw" =~ ^-?[0-9]+$ ]] || continue
    temp_c=$((raw / 1000))
    (( temp_c > best )) && best="$temp_c"
  done

  (( best > 0 )) || return 0
  local suffix=""
  (( best >= TEMP_WARN )) && suffix='!'
  printf '%s %s°C%s' "$(icon_temp)" "$best" "$suffix"
}

get_memory() {
  [[ "$SHOW_MEMORY" -eq 1 ]] || return 0
  [[ -x "$FREEBIN" ]] || return 0

  local used total pct
  read -r used total < <("$FREEBIN" -m 2>/dev/null | awk '/^Mem:/ {print $3, $2}')
  [[ -n "${used:-}" && -n "${total:-}" && "$total" -gt 0 ]] || return 0

  pct=$(( used * 100 / total ))
  printf '%s %s%%' "$(icon_memory)" "$pct"
}

get_uptime() {
  [[ "$SHOW_UPTIME" -eq 1 ]] || return 0
  [[ -x "$UPTIMEBIN" ]] || return 0

  local up
  up="$("$UPTIMEBIN" -p 2>/dev/null | sed 's/^up //')"
  [[ -n "${up:-}" ]] || return 0
  printf '%s %s' "$(icon_uptime)" "$up"
}

# next-event removed: the calendar event is no longer shown in the status bar.

get_updates() {
  [[ "$SHOW_UPDATES" -eq 1 ]] || return 0
  [[ -x "$CHECKUPDATES" ]] || return 0

  local now stamp age pac_count aur_count total db_stamp saved_db_stamp
  now="$($DATEBIN +%s 2>/dev/null || printf '0')"
  stamp=0

  if [[ -r "$UPDATES_STAMP" ]]; then
    stamp="$(tr -d '[:space:]' < "$UPDATES_STAMP" 2>/dev/null)"
    stamp="${stamp:-0}"
  fi

  [[ "$stamp" =~ ^[0-9]+$ ]] || stamp=0
  [[ "$UPDATES_CACHE_SECONDS" =~ ^[0-9]+$ ]] || UPDATES_CACHE_SECONDS=1800
  age=$((now - stamp))
  # Package installation/upgrade changes the local package database.
  # Cache remains time-bound even if a package manager uses different paths.
  db_stamp="$("$CHECKUPDATES" --db-stamp 2>/dev/null || true)"
  saved_db_stamp="$(cat "$UPDATES_DB_STAMP" 2>/dev/null || true)"

  if [[ -r "$UPDATES_FILE" && "$db_stamp" == "$saved_db_stamp" && "$age" -ge 0 && "$age" -lt "$UPDATES_CACHE_SECONDS" ]]; then
    total="$(tr -d '[:space:]' < "$UPDATES_FILE" 2>/dev/null)"
    total="${total:-0}"
  else
    pac_count="$("$CHECKUPDATES" 2>/dev/null || printf '0')"
    [[ "$pac_count" =~ ^[0-9]+$ ]] || pac_count=0
    pac_count="${pac_count:-0}"
    aur_count=0
    if command -v checkupdates >/dev/null 2>&1 && command -v paru >/dev/null 2>&1; then
      aur_count="$(paru -Qua 2>/dev/null | wc -l | tr -d '[:space:]')"
    elif command -v checkupdates >/dev/null 2>&1 && command -v yay >/dev/null 2>&1; then
      aur_count="$(yay -Qua 2>/dev/null | wc -l | tr -d '[:space:]')"
    fi
    [[ "$aur_count" =~ ^[0-9]+$ ]] || aur_count=0
    total=$((pac_count + aur_count))
    printf '%s\n' "$total" > "$UPDATES_FILE" 2>/dev/null || true
    printf '%s\n' "$now" > "$UPDATES_STAMP" 2>/dev/null || true
    printf '%s\n' "$db_stamp" > "$UPDATES_DB_STAMP" 2>/dev/null || true
  fi

  if [[ "${total:-0}" -gt 0 ]]; then
    printf '%s %s' "$(icon_updates)" "$total"
  fi
}

get_volume() {
  [[ "$SHOW_VOLUME" -eq 1 ]] || return 0

  if command -v wpctl >/dev/null 2>&1; then
    local out vol
    out="$(wpctl get-volume @DEFAULT_AUDIO_SINK@ 2>/dev/null)" || return 0

    if printf '%s' "$out" | grep -q 'MUTED'; then
      printf '%s mute' "$(icon_volume_mute)"
      return 0
    fi

    vol="$(printf '%s\n' "$out" | awk '{print int($2 * 100)}')"
    printf '%s %s%%' "$(icon_volume)" "${vol:-0}"
    return 0
  fi

  if command -v amixer >/dev/null 2>&1; then
    local amix level
    amix="$(amixer get Master 2>/dev/null)"
    [[ -n "${amix:-}" ]] || return 0

    if printf '%s' "$amix" | grep -q '\[off\]'; then
      printf '%s mute' "$(icon_volume_mute)"
      return 0
    fi

    level="$(printf '%s\n' "$amix" | awk -F'[][]' '/%/ {print $2; exit}')"
    [[ -n "${level:-}" ]] && printf '%s %s' "$(icon_volume)" "$level"
    return 0
  fi
}

pick_first_existing_dir() {
  local dir
  for dir in "$@"; do
    [[ -d "$dir" ]] && {
      printf '%s' "$dir"
      return 0
    }
  done
  return 1
}

get_media_paths() {
  local music_dir photos_dir videos_dir

  if [[ -n "${MEDIA_MUSIC_DIR:-}" && -d "$MEDIA_MUSIC_DIR" ]]; then
    music_dir="$MEDIA_MUSIC_DIR"
  else
    music_dir="$(pick_first_existing_dir \
      "$HOME/Music" \
      "$HOME/mp3" \
      "$HOME/media/Music")"
  fi

  if [[ -n "${MEDIA_PHOTOS_DIR:-}" && -d "$MEDIA_PHOTOS_DIR" ]]; then
    photos_dir="$MEDIA_PHOTOS_DIR"
  else
    photos_dir="$(pick_first_existing_dir \
      "$HOME/Pictures" \
      "$HOME/Photos" \
      "$HOME/media/Pictures")"
  fi

  if [[ -n "${MEDIA_VIDEOS_DIR:-}" && -d "$MEDIA_VIDEOS_DIR" ]]; then
    videos_dir="$MEDIA_VIDEOS_DIR"
  else
    videos_dir="$(pick_first_existing_dir \
      "$HOME/Videos" \
      "$HOME/media/Videos")"
  fi

  printf '%s\n%s\n%s\n' \
    "${music_dir:-}" \
    "${photos_dir:-}" \
    "${videos_dir:-}"
}

count_files_in_dir() {
  local dir="$1"
  shift || true

  [[ -n "${dir:-}" && -e "$dir" ]] || {
    printf '0'
    return 0
  }

  find -L "$dir" \( -type f \( "$@" \) \) 2>/dev/null | wc -l | tr -d '[:space:]'
}

get_media_counts() {
  [[ "$SHOW_MEDIA" -eq 1 ]] || return 0

  local now stamp age media_line
  now="$($DATEBIN +%s 2>/dev/null || printf '0')"
  stamp=0

  if [[ -r "$MEDIA_CACHE_STAMP" ]]; then
    stamp="$(tr -d '[:space:]' < "$MEDIA_CACHE_STAMP" 2>/dev/null)"
    stamp="${stamp:-0}"
  fi

  age=$((now - stamp))

  if [[ -r "$MEDIA_CACHE_FILE" && "$age" -lt "$MEDIA_CACHE_SECONDS" ]]; then
    cat "$MEDIA_CACHE_FILE"
    return 0
  fi

  local music_dir photos_dir videos_dir
  local mp3_count photo_count video_count
  local -a media_paths=()

  mapfile -t media_paths < <(get_media_paths)
  music_dir="${media_paths[0]:-}"
  photos_dir="${media_paths[1]:-}"
  videos_dir="${media_paths[2]:-}"

  mp3_count="$(count_files_in_dir "$music_dir" \
    -iname "*.mp3" -o -iname "*.flac" -o -iname "*.wav" -o -iname "*.ogg" -o -iname "*.m4a" -o -iname "*.opus")"

  photo_count="$(count_files_in_dir "$photos_dir" \
    -iname "*.jpg" -o -iname "*.jpeg" -o -iname "*.png" -o -iname "*.webp" -o -iname "*.heic" -o -iname "*.gif" -o -iname "*.avif")"

  video_count="$(count_files_in_dir "$videos_dir" \
    -iname "*.mp4" -o -iname "*.mkv" -o -iname "*.mov" -o -iname "*.avi" -o -iname "*.webm" -o -iname "*.m4v")"

  media_line="$(icon_music) ${mp3_count:-0}"$'\n'"$(icon_photos) ${photo_count:-0}"$'\n'"$(icon_videos) ${video_count:-0}"

  printf '%s\n' "$media_line" > "$MEDIA_CACHE_FILE" 2>/dev/null || true
  printf '%s\n' "$now" > "$MEDIA_CACHE_STAMP" 2>/dev/null || true

  printf '%s' "$media_line"
}

get_disk() {
  [[ "$SHOW_DISK" -eq 1 ]] || return 0

  local percent mountpoint
  mountpoint="${1:-/}"

  percent="$(df -P "$mountpoint" 2>/dev/null | awk 'NR==2 {gsub("%","",$5); print $5}')"
  [[ "$percent" =~ ^[0-9]+$ ]] || return 0

  printf '%s %s%%' "$(icon_disk)" "$percent"
}

get_cpu() {
  [[ "$SHOW_CPU" -eq 1 ]] || return 0
  [[ -r /proc/stat ]] || return 0

  local line total idle prev_total prev_idle diff_total diff_idle pct
  local f="$PROVIDER_DIR/cpu.stat"
  total=0; idle=0
  line="$(awk '/^cpu /{s=0; for(i=2;i<=NF;i++) s+=$i; print s, $5}' /proc/stat 2>/dev/null)"
  [[ -n "$line" ]] || return 0
  total="${line%% *}"; idle="${line##* }"

  prev_total=0; prev_idle=0
  if [[ -r "$f" ]]; then read -r prev_total prev_idle < "$f" 2>/dev/null || true; fi
  printf '%s %s\n' "$total" "$idle" > "$f" 2>/dev/null || true

  [[ "$prev_total" =~ ^[0-9]+$ ]] || return 0
  diff_total=$(( total - prev_total )); diff_idle=$(( idle - prev_idle ))
  (( diff_total > 0 )) || return 0
  pct=$(( (100 * (diff_total - diff_idle)) / diff_total ))
  printf '%s %s%%' "$(icon_cpu)" "$pct"
}

get_load() {
  [[ "$SHOW_LOAD" -eq 1 ]] || return 0

  local load
  load="$(awk '{printf "%.2f", $1}' /proc/loadavg 2>/dev/null)"
  [[ -n "${load:-}" ]] || return 0

  printf '%s %s' "$(icon_load)" "$load"
}

get_bluetooth() {
  [[ "$SHOW_BLUETOOTH" -eq 1 ]] || return 0
  command -v bluetoothctl >/dev/null 2>&1 || return 0

  local n
  n="$(bluetoothctl devices Connected 2>/dev/null | wc -l | tr -d '[:space:]')"
  [[ "${n:-0}" =~ ^[0-9]+$ ]] || n=0
  (( n > 0 )) || return 0
  printf '%s %s' "$(icon_bluetooth)" "$n"
}

get_mic() {
  [[ "$SHOW_MIC" -eq 1 ]] || return 0
  command -v wpctl >/dev/null 2>&1 || return 0

  local out
  out="$(wpctl get-volume @DEFAULT_AUDIO_SOURCE@ 2>/dev/null)" || return 0
  printf '%s' "$out" | grep -q 'MUTED' && printf '%s' "$(icon_mic_mute)"
}

get_dnd() {
  [[ "$SHOW_DND" -eq 1 ]] || return 0
  command -v dunstctl >/dev/null 2>&1 || return 0

  local paused
  paused="$(dunstctl is-paused 2>/dev/null || true)"
  [[ "$paused" == "true" ]] && printf '%s' "$(icon_dnd)"
}

get_recording() {
  [[ "$SHOW_RECORDING" -eq 1 ]] || return 0
  command -v pgrep >/dev/null 2>&1 || return 0

  if pgrep -u "$(id -u)" -f 'wf-recorder' >/dev/null 2>&1 \
    || pgrep -u "$(id -u)" -f 'ffmpeg .*x11grab' >/dev/null 2>&1; then
    printf '%s' "$(icon_rec)"
  fi
}

get_caffeine() {
  [[ "$SHOW_CAFFEINE" -eq 1 ]] || return 0
  [[ -e "${XDG_CACHE_HOME:-$HOME/.cache}/nirupi/caffeine" ]] && printf '%s' "$(icon_caffeine)"
}

# Best-effort Nextcloud status without a tray, via the StatusNotifierItem over
# the session bus. Falls back to "running/offline" when DBus is unavailable.
nextcloud_sni_state() {
  local names name id status icon
  if command -v gdbus >/dev/null 2>&1; then
    names="$(gdbus call --session --dest org.freedesktop.DBus \
      --object-path /org/freedesktop/DBus \
      --method org.freedesktop.DBus.ListNames 2>/dev/null || true)"
  elif command -v busctl >/dev/null 2>&1; then
    names="$(busctl --user --no-pager list --no-legend 2>/dev/null | awk '{print $1}')"
  else
    return 0
  fi
  while IFS= read -r name; do
    [[ "$name" == *StatusNotifierItem* ]] || continue
    id="$(gdbus call --session --dest "$name" --object-path /StatusNotifierItem \
      --method org.freedesktop.DBus.Properties.Get org.kde.StatusNotifierItem Id 2>/dev/null || true)"
    [[ "$id" == *extcloud* ]] || continue
    status="$(gdbus call --session --dest "$name" --object-path /StatusNotifierItem \
      --method org.freedesktop.DBus.Properties.Get org.kde.StatusNotifierItem Status 2>/dev/null || true)"
    icon="$(gdbus call --session --dest "$name" --object-path /StatusNotifierItem \
      --method org.freedesktop.DBus.Properties.Get org.kde.StatusNotifierItem IconName 2>/dev/null || true)"
    case "$status" in
      *NeedsAttention*|*Attention*) printf 'attention'; return 0;;
    esac
    case "$icon" in
      *error*|*Error*) printf 'error'; return 0;;
      *sync*|*Sync*) printf 'sync'; return 0;;
    esac
    printf 'ok'; return 0
  done <<< "$(printf '%s\n' "$names" | tr -d '(),' | tr ' ' '\n')"
}

get_nextcloud() {
  [[ "$SHOW_NEXTCLOUD" -eq 1 ]] || return 0
  command -v nextcloud >/dev/null 2>&1 || return 0

  if ! pgrep -u "$(id -u)" -x nextcloud >/dev/null 2>&1; then
    printf '%s' "$(icon_cloud_off)"
    return 0
  fi
  case "$(nextcloud_sni_state)" in
    attention|error) printf '%s!' "$(icon_cloud)";;
    *) printf '%s' "$(icon_cloud)";;
  esac
}

get_now_playing() {
  [[ "$SHOW_NOW_PLAYING" -eq 1 ]] || return 0

  local player status title artist app raw_text visible
  local preferred_list player_name

  if command -v playerctl >/dev/null 2>&1; then
    for player_name in $NOW_PLAYING_PREFERRED_PLAYERS; do
      status="$(playerctl -p "$player_name" status 2>/dev/null || true)"
      [[ "$status" == "Playing" ]] || continue

      artist="$(playerctl -p "$player_name" metadata artist 2>/dev/null || true)"
      title="$(playerctl -p "$player_name" metadata title 2>/dev/null || true)"
      app="$(normalize_player_name "$player_name")"

      if [[ -n "$artist" && -n "$title" ]]; then
        raw_text="$artist - $title"
      elif [[ -n "$title" ]]; then
        raw_text="$title"
      else
        raw_text="$app"
      fi

      if [[ "${NOW_PLAYING_TEMPLATE:-0}" == 1 ]]; then
        printf '%s\n%s\n' "$app" "$raw_text" > "$NP_CURRENT_FILE"
        printf '%s' '__NIRUPI_NOW_PLAYING__'
        return 0
      fi

      visible="$(render_now_playing_text "$raw_text")"
      if [[ "$SHOW_PLAYER_NAME" -eq 1 ]]; then
        printf '%s %s%s%s' "$(icon_play)" "$app" "${NOW_PLAYING_LABEL_SEPARATOR:-: }" "$visible"
      else
        printf '%s %s' "$(icon_play)" "$visible"
      fi
      return 0
    done

    while IFS= read -r player; do
      [[ -n "$player" ]] || continue
      status="$(playerctl -p "$player" status 2>/dev/null || true)"
      [[ "$status" == "Playing" ]] || continue

      artist="$(playerctl -p "$player" metadata artist 2>/dev/null || true)"
      title="$(playerctl -p "$player" metadata title 2>/dev/null || true)"
      app="$(normalize_player_name "$player")"

      if [[ -n "$artist" && -n "$title" ]]; then
        raw_text="$artist - $title"
      elif [[ -n "$title" ]]; then
        raw_text="$title"
      else
        raw_text="$app"
      fi

      if [[ "${NOW_PLAYING_TEMPLATE:-0}" == 1 ]]; then
        printf '%s\n%s\n' "$app" "$raw_text" > "$NP_CURRENT_FILE"
        printf '%s' '__NIRUPI_NOW_PLAYING__'
        return 0
      fi

      visible="$(render_now_playing_text "$raw_text")"
      if [[ "$SHOW_PLAYER_NAME" -eq 1 ]]; then
        printf '%s %s%s%s' "$(icon_play)" "$app" "${NOW_PLAYING_LABEL_SEPARATOR:-: }" "$visible"
      else
        printf '%s %s' "$(icon_play)" "$visible"
      fi
      return 0
    done < <(playerctl -l 2>/dev/null)
  fi

  if command -v cmus-remote >/dev/null 2>&1; then
    local cmus_status cmus_artist cmus_title
    cmus_status="$(cmus-remote -Q 2>/dev/null | awk '/^status / {print $2; exit}')"
    if [[ "$cmus_status" == "playing" ]]; then
      cmus_artist="$(cmus-remote -Q 2>/dev/null | awk '/^tag artist / {sub(/^tag artist /,""); print; exit}')"
      cmus_title="$(cmus-remote -Q 2>/dev/null | awk '/^tag title / {sub(/^tag title /,""); print; exit}')"
      app="cmus"

      if [[ -n "$cmus_artist" && -n "$cmus_title" ]]; then
        raw_text="$cmus_artist - $cmus_title"
      elif [[ -n "$cmus_title" ]]; then
        raw_text="$cmus_title"
      else
        raw_text="$app"
      fi

      if [[ "${NOW_PLAYING_TEMPLATE:-0}" == 1 ]]; then
        printf '%s\n%s\n' "$app" "$raw_text" > "$NP_CURRENT_FILE"
        printf '%s' '__NIRUPI_NOW_PLAYING__'
        return 0
      fi

      visible="$(render_now_playing_text "$raw_text")"
      if [[ "$SHOW_PLAYER_NAME" -eq 1 ]]; then
        printf '%s %s%s%s' "$(icon_play)" "$app" "${NOW_PLAYING_LABEL_SEPARATOR:-: }" "$visible"
      else
        printf '%s %s' "$(icon_play)" "$visible"
      fi
      return 0
    fi
  fi

  [[ "${NOW_PLAYING_TEMPLATE:-0}" == 1 ]] && : > "$NP_CURRENT_FILE"
  NP_LAST_TEXT=""
  NP_FIRST_SEEN=0
  NP_OFFSET=0
  NP_STATE="pause"
  return 0
}

build_status_line() {
  local kernel host weather network battery temp updates media volume nowplaying memory uptime disk cpu load bluetooth nextcloud dnd mic recording caffeine datepart timepart
  local -a parts=()

  kernel="$(provider_cached kernel 3600 get_kernel)"
  host="$(provider_cached host 3600 get_hostname)"
  network="$(provider_cached network "$NETWORK_CACHE_SECONDS" get_network)"
  nextcloud="$(provider_cached nextcloud "$NEXTCLOUD_CACHE_SECONDS" get_nextcloud)"
  battery="$(get_battery || true)"
  temp="$(get_temp_high || true)"
  updates="$(get_updates || true)"
  media="$(get_media_counts || true)"
  volume="$(get_volume || true)"
  mic="$(get_mic || true)"
  dnd="$(get_dnd || true)"
  recording="$(get_recording || true)"
  caffeine="$(get_caffeine || true)"
  nowplaying="$(get_now_playing || true)"
  memory="$(get_memory || true)"
  uptime="$(get_uptime || true)"
  disk="$(get_disk || true)"
  cpu="$(get_cpu || true)"
  load="$(get_load || true)"
  bluetooth="$(get_bluetooth || true)"
  weather="$(get_weather || true)"
  datepart=""
  timepart=""
  [[ "$SHOW_DATE" -eq 1 ]] && datepart="$($DATEBIN '+%Y-%m-%d w%V')"
  [[ "$SHOW_TIME" -eq 1 ]] && timepart="$($DATEBIN '+%H:%M')"

  [[ -n "${volume:-}" ]] && volume="$(sect 6 "$volume")"
  [[ -n "${network:-}" ]] && network="$(sect 8 "$network")"
  [[ -n "${nextcloud:-}" ]] && nextcloud="$(sect 7 "$nextcloud")"
  [[ -n "${battery:-}" ]] && battery="$(sect 14 "$battery")"
  [[ -n "${temp:-}" ]] && temp="$(sect 15 "$temp")"
  if [[ -n "${media:-}" ]]; then
    local -a _mp=()
    mapfile -t _mp <<< "$media"
    # Separate clickable sections so each icon opens its own folder (16/9/10).
    media="$(sect 16 "${_mp[0]:-}") $(sect 22 "${_mp[1]:-}") $(sect 30 "${_mp[2]:-}")"
  fi
  [[ -n "${nowplaying:-}" ]] && nowplaying="$(sect 17 "$nowplaying")"
  [[ -n "${mic:-}" ]] && mic="$(sect 18 "$mic")"
  [[ -n "${dnd:-}" ]] && dnd="$(sect 19 "$dnd")"
  [[ -n "${recording:-}" ]] && recording="$(sect 20 "$recording")"
  [[ -n "${caffeine:-}" ]] && caffeine="$(sect 31 "$caffeine")"
  [[ -n "${memory:-}" ]] && memory="$(sect 21 "$memory")"
  [[ -n "${uptime:-}" ]] && uptime="$(sect 21 "$uptime")"
  [[ -n "${disk:-}" ]] && disk="$(sect 23 "$disk")"
  [[ -n "${cpu:-}" ]] && cpu="$(sect 24 "$cpu")"
  [[ -n "${load:-}" ]] && load="$(sect 25 "$load")"
  [[ -n "${bluetooth:-}" ]] && bluetooth="$(sect 26 "$bluetooth")"
  [[ -n "${kernel:-}" ]] && kernel="$(sect 27 "$kernel")"
  [[ -n "${host:-}" ]] && host="$(sect 28 "$host")"
  [[ -n "${datepart:-}" ]] && datepart="$(sect 29 "$datepart")"
  [[ -n "${timepart:-}" ]] && timepart="$(sect 29 "$timepart")"
  [[ -n "${updates:-}" ]] && updates="$(sect 5 "$updates")"
  [[ -n "${weather:-}" ]] && weather="$(sect 4 "$weather")"
  if bar_color_on; then
    [[ "$recording" == *"$(icon_rec)"* ]] && recording="$(colorc "$NIRUPI_C_RED" "$recording")"
    [[ "$dnd" == *"$(icon_dnd)"* ]] && dnd="$(colorc "$NIRUPI_C_MUTED" "$dnd")"
    [[ "$caffeine" == *"$(icon_caffeine)"* ]] && caffeine="$(colorc "$NIRUPI_C_YELLOW" "$caffeine")"
    [[ "$battery" == *"!"* ]] && battery="$(colorc "$NIRUPI_C_RED" "$battery")"
    [[ "$temp" == *"!"* ]] && temp="$(colorc "$NIRUPI_C_YELLOW" "$temp")"
    [[ -n "${updates:-}" ]] && updates="$(colorc "$NIRUPI_C_BLUE" "$updates")"
  fi

  [[ -n "${media:-}" ]] && parts+=("$media")
  [[ -n "${volume:-}" ]] && parts+=("$volume")
  [[ -n "${mic:-}" ]] && parts+=("$mic")
  [[ -n "${nowplaying:-}" ]] && parts+=("$nowplaying")
  [[ -n "${network:-}" ]] && parts+=("$network")
  [[ -n "${nextcloud:-}" ]] && parts+=("$nextcloud")
  [[ -n "${battery:-}" ]] && parts+=("$battery")
  [[ -n "${temp:-}" ]] && parts+=("$temp")
  [[ -n "${dnd:-}" ]] && parts+=("$dnd")
  [[ -n "${recording:-}" ]] && parts+=("$recording")
  [[ -n "${caffeine:-}" ]] && parts+=("$caffeine")
  [[ -n "${memory:-}" ]] && parts+=("$memory")
  [[ -n "${uptime:-}" ]] && parts+=("$uptime")
  [[ -n "${disk:-}" ]] && parts+=("$disk")
  [[ -n "${cpu:-}" ]] && parts+=("$cpu")
  [[ -n "${load:-}" ]] && parts+=("$load")
  [[ -n "${bluetooth:-}" ]] && parts+=("$bluetooth")
  [[ -n "${updates:-}" ]] && parts+=("$updates")
  [[ -n "${weather:-}" ]] && parts+=("$weather")

  [[ -n "${kernel:-}" ]] && parts+=("$kernel")
  [[ -n "${host:-}" ]] && parts+=("$host")
  [[ -n "${datepart:-}" ]] && parts+=("$datepart")
  [[ -n "${timepart:-}" ]] && parts+=("$timepart")

  if bar_color_on; then
    parts=("$(colorc "$NIRUPI_C_CYAN" "$(sect 1 "$(icon_agent)")")" "${parts[@]}")
  else
    parts=("$(sect 1 "$(icon_agent)")" "${parts[@]}")
  fi
  printf '[ %s ]' "$(printf '%s\n' "${parts[@]}" | sed 's/^[[:space:]]*//; s/[[:space:]]*$//' | paste -sd '|' - | sed 's/|/ | /g')"
}

# Heavy/system probes run at the original interval. Only the cached music
# text is animated between probes; playerctl and network tools are not polled
# for every animation frame.
[[ "$INTERVAL" =~ ^[1-9][0-9]*$ ]] || INTERVAL=2
[[ "$NOW_PLAYING_FRAME_INTERVAL" =~ ^(0\\.[1-9][0-9]*|1(\\.0+)?)$ ]] || NOW_PLAYING_FRAME_INTERVAL=0.3
[[ "$NOW_PLAYING_SCROLL_STEP" =~ ^[1-9][0-9]*$ ]] || NOW_PLAYING_SCROLL_STEP=1

render_cached_now_playing() {
  local app="" raw="" visible=""
  [[ -r "$NP_CURRENT_FILE" ]] || return 0
  { IFS= read -r app || true; IFS= read -r raw || true; } < "$NP_CURRENT_FILE"
  [[ -n "$raw" ]] || return 0
  visible="$(render_now_playing_text "$raw")"
  if [[ "$SHOW_PLAYER_NAME" -eq 1 ]]; then
    printf '%s %s%s%s' "$(icon_play)" "$app" "${NOW_PLAYING_LABEL_SEPARATOR:-: }" "$visible"
  else
    printf '%s %s' "$(icon_play)" "$visible"
  fi
}

# Prefer one-character frames; user config can still request larger steps.
# The system line is rebuilt only at INTERVAL, including metadata detection.
# One-shot modes for scripts and `nirupi status`.
case "${1:-}" in
  --once)
    build_status_line | tr -d '\000-\037' | sed -e 's/\^[^^]*\^//g'
    exit 0;;
  --json)
    _jes(){ printf '%s' "$1" | tr -d '\000-\037' | sed -e 's/\\/\\\\/g' -e 's/"/\\"/g'; }
    printf '{"kernel":"%s","host":"%s","network":"%s","nextcloud":"%s","battery":"%s","temp":"%s","updates":"%s","volume":"%s","weather":"%s","date":"%s","time":"%s"}\n' \
      "$(_jes "$(get_kernel)")" "$(_jes "$(get_hostname)")" "$(_jes "$(get_network)")" \
      "$(_jes "$(get_nextcloud)")" "$(_jes "$(get_battery)")" "$(_jes "$(get_temp_high)")" \
      "$(_jes "$(get_updates)")" "$(_jes "$(get_volume)")" "$(_jes "$(get_weather)")" \
      "$(_jes "$("$DATEBIN" '+%Y-%m-%d')")" "$(_jes "$("$DATEBIN" '+%H:%M')")"
    exit 0;;
esac
NOW_PLAYING_TEMPLATE=1
last_system_update=0
template=""
while :; do
  now_seconds="$("$DATEBIN" +%s 2>/dev/null || printf '0')"
  if [[ -z "$template" ]] || (( now_seconds - last_system_update >= INTERVAL )); then
    template="$(build_status_line)"
    last_system_update="$now_seconds"
  fi
  if [[ "$template" == *'__NIRUPI_NOW_PLAYING__'* ]]; then
    music="$(render_cached_now_playing)"
    line="${template/__NIRUPI_NOW_PLAYING__/$music}"
  else
    line="$template"
  fi
  [[ -n "$XSETROOT" ]] && "$XSETROOT" -name "$line" 2>/dev/null || true
  sleep "$NOW_PLAYING_FRAME_INTERVAL"
done
